class LRU:
    def __init__(self, maxsize):
        self.maxsize = maxsize
        self.cache = {}
        self.order = []
    def get(self, k):
        if k in self.cache:
            self.order.remove(k)
            self.order.append(k)
            return self.cache[k]
        return -1
    def put(self, k, v):
        if len(self.cache) >= self.maxsize:
            evict = self.order.pop(0)
            del self.cache[evict]
        self.cache[k] = v
        self.order.append(k)
